// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address initialOwner) public {
        vm.assume(initialOwner != address(0));

        // Deploy fresh C and initialize via the proxy's initializer
        address impl = address(new C());
        vm.prank(initialOwner);
        c = C(impl);
        c.initialize(1, 1, "test", address(0x1234));

        // The stored owner is the initialOwner as set during initialization.
        // Reference returns that address; mutant returns address(0).
        assertEq(c.owner(), initialOwner, "owner() must return the initial owner");
    }
}

