// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialOwner) public {
        vm.assume(initialOwner != address(0));
        // Initialize with the fuzzed owner
        c.initialize(1, 1, "test", address(this));
        // Transfer ownership to the fuzzed address
        vm.prank(address(this));
        c.transferOwnership(initialOwner);
        // Accept ownership as the new owner
        vm.prank(initialOwner);
        c.acceptOwnership();
        // Now owner() must return initialOwner exactly
        assertTrue(c.owner() == initialOwner);
    }
}

